def mk(g):
    def res(p):
        k,pp,b=p
        A=np.column_stack([x**1.5, np.sin(k*np.sqrt(t)), t*np.log(t)*x**1.5, x**pp*g(v,b)])
        c=lstsq(A,y,rcond=None)[0]; return y-A@c
    return res
